  count: docs.length,
  documents: docs.map((d) => ({
    id: d.id, title: d.title, sourceUrl: d.sourceUrl, chunkCount: d.chunkCount,
    tags: d.tags || [], updatedAt: d.updatedAt, createdAt: d.createdAt
  }))
};

